function passengers(tr){const stops=tr.calls.filter(c=>c.stop),out=[];for(let j=-2;j<stops.length-1;j++)for(let p=0;p<2;p++){const enter=j<0?-Infinity:stops[j].arr+5.7+p*.65,exit=stops[Math.min(Math.max(0,j+2),stops.length-1)].arr+1.8+p*.65;if(time<enter||time>exit+3.2)continue;const phase=time>=exit?'alighting':time<enter+3.2?'boarding':'seated';out.push({id:tr.id+':'+j+':'+p,phase,progress:phase==='seated'?1:clamp((time-(phase==='boarding'?enter:exit))/3.2,0,1),seat:((j+2)*2+p)%4,color:['#78998e','#bd977c','#8196ac','#b499a8'][((j+2)*2+p)%4]});}return out;}
function drawPassengers(tr,platform){for(const p of passengers(tr)){if(p.phase==='seated'){if(!platform)person([180,310,875,1035][p.seat],548,p.color);continue;}const u=p.phase==='boarding'?p.progress:1-p.progress;if(platform){if(u<.5)person(600+(p.seat%2?1:-1)*(1-u*2)*100,430+(1-u*2)*112,p.color,time*9);}else if(u>=.5){const f=(u-.5)*2;person(600+([180,310,875,1035][p.seat]-600)*f,598-50*f,p.color,time*9);}}}
