function monoQuestInteract(id){if(scene!=='monoTown'||monoStation<5)return false;const q=monoTasks[monoStation];if(id==='monoQuest'){if(profile.monoDone.includes(monoStation)){dialog('案内人','ありがとう。また来てね。','ありがとう。またきてね。','任务已完成，奖励已经收下。欢迎继续散步。');return true;}if(q.steps.every(k=>profile.monoQuestSteps.includes(k))){profile.monoDone.push(monoStation);profile.monoActive=null;profile.coins+=q.reward;unlock('souvenirs',monoNames[monoStation]+'の探険カード');save();chime();dialog('できた！ '+q.title,'よく見つけたね。ありがとう。','よくみつけたね。ありがとう。',`完成本站探险！+${q.reward} 游戏币，并获得纪念卡。奖励与进度已经保存。`);}else{profile.monoActive=monoStation;save();dialog('案内人 · '+q.title,'いっしょに、まちを探検しよう。','いっしょに、まちをたんけんしよう。',q.summary+' 每个地点靠近按 E，完成后回来找我。');}updateUI();return true;}if(!q.steps.includes(id))return false;if(profile.monoActive===monoStation&&!profile.monoDone.includes(monoStation)){unlock('monoQuestSteps',id);chime();}const info={riverFlower:['川辺の花','きれいな花だね。','岸边的小花在阳光下开着。站在步道上观察，记入探险手帐。'],riverBird:['小鳥','鳥の声が聞こえるね。','小鸟在河岸边唱歌，听听它的声音。'],riverLeaf:['葉っぱ','葉っぱの形が、おもしろいね。','看看叶子的形状和纹路，完成自然观察。'],templeGuide:['高幡不動尊','お寺のまちを、歩こう。','高幡不動尊是本站附近的重要地标。这里是游戏化缩略的入口介绍，暂不开放寺院内部。'],keioGuide:['京王線への乗換案内','京王線は、こちらです。','现实中高幡不動可以换乘京王線。本版可步行到左边的京王站入口，刷卡搭動物園線到多摩動物公園。京王本线尚未开放。回京王堀之内，请坐单轨到多摩センター，再换京王相模原線。']}[id];if(id==='riverBird'){tone(1400,.09);tone(1900,.1,'sine',.04,.12);}dialog(info[0],info[1],({riverFlower:'きれいな はなだね。',riverBird:'とりのこえが きこえるね。',riverLeaf:'はっぱの かたちが、おもしろいね。',templeGuide:'おてらのまちを、あるこう。',keioGuide:'けいおうせんは、こちらです。'})[id],info[2]+(profile.monoQuestSteps.includes(id)?' ✓ 已记入手帐。':' 接任务后再来，可以记录发现。'));updateUI();return true;}
