function monoInteract(id){if(monoQuestInteract(id))return true;if(id==='monoReverse'){monoDirection=monoStation===0?1:monoStation===monoNames.length-1?-1:-monoDirection;go('monoPlatform',170,620);toast(monoDirection===1?'上北台方面（本版は高幡不動まで）':'多摩センター方面');return true;}if(id==='monoEntrance'){monoRide=null;go('monoHall',600,670);return true;}if(id==='monoGate'){if(monoPaid){const fare=monoEntry===monoStation?0:50;if(profile.ic<fare){toast('先到充值机精算，零钱不足可领取旅行援助。');return true;}profile.ic-=fare;monoPaid=false;monoEntry=null;toast(`ピッ · 出場 −${fare} ゲーム円`);}else{if(profile.ic<50){toast('IC余额不足，请先充值。');return true;}monoPaid=true;monoEntry=monoStation;toast('ピッ · 多摩モノレール入場');}save();tone(1320,.14);gateUntil=time+1.1;transition={start:time,from:{...player},to:{x:600,y:monoPaid?312:465},duration:1};path=[];updateUI();return true;}if(id==='monoCharge'){if(profile.coins<300){openModal('<h2>チャージのお手伝い</h2><button data-do="aid">领取旅行援助</button>');return true;}profile.coins-=300;profile.ic+=300;save();chime();toast('チャージ +300');updateUI();return true;}if(id==='monoStairs'){if(!monoPaid){toast('先刷IC卡进站。');return true;}go('monoPlatform',170,620);return true;}if(id==='monoDown'){go('monoHall',300,230);return true;}if(id==='monoOutside'){if(monoPaid){toast('请先刷卡出站。');return true;}go(monoStation===0?'monoWalk':'monoTown',600,monoStation===0?590:370);return true;}if(id==='monoTrain'){if(monoStation+monoDirection<0||monoStation+monoDirection>=monoNames.length){toast('运行边界，请走到另一方向的站台。');return true;}const t=monoBoardable();if(!t){toast('モノレールが来るまで待とう。');return true;}monoRide={start:t.start,dir:t.dir};profile.monoRides=(profile.monoRides||0)+1;unlock('models','多摩モノレール1000系');save();go('monoCar',600,620);say('次は、'+monoNames[monoStation+monoDirection]+'です。','','下一站是'+monoNames[monoStation+monoDirection]+'。单轨车在高架导轨上行驶。');return true;}if(id==='monoDoor'){const s=monoState(monoRide.start,monoRide.dir);if(!s.door){toast('行驶中，等停稳开门后再下车。');return true;}monoStation=s.at;monoDirection=monoStation===0?1:monoStation===monoNames.length-1?-1:monoRide.dir;monoRide=null;go('monoPlatform',600,465);chime();return true;}if(id==='monoPark'){unlock('souvenirs',monoNames[monoStation]+'のスタンプ');chime();dialog(monoNames[monoStation]+'のさんぽ','旅のスタンプを、どうぞ。','たびの すたんぷを、どうぞ。',monoThemes[monoStation]+'。获得本站纪念印章！可回站继续向北，或走到反方向站台返回多摩センター。动物园与大学内部暂不开放。');return true;}return false;}
