function walkable(x,y){let bounds={x:50,y:70,w:1100,h:680};if(scene==='platform'||scene==='monoPlatform'||scene==='zooPlatform')bounds={x:55,y:425,w:1090,h:275};if(scene==='home'||scene==='shop')bounds={x:150,y:210,w:900,h:485};if(scene==='concourse'||scene==='monoHall'||scene==='zooHall')bounds={x:70,y:100,w:1060,h:630};if(scene==='train'||scene==='monoCar'||scene==='zooCar')bounds={x:75,y:583,w:1050,h:160};if(scene==='monoWalk')bounds={x:100,y:380,w:990,h:325};if(x<bounds.x||x>bounds.x+bounds.w||y<bounds.y||y>bounds.y+bounds.h)return false;return !obstacles().some(o=>x>o.x-10&&x<o.x+o.w+10&&y>o.y-8&&y<o.y+o.h+10);}
function walkTo(x,y){if(!started||modal||transition||scene==='restaurant'&&dining?.seat!==null)return;const cell=20,cols=60,rows=40;
 let sx=Math.round(player.x/cell),sy=Math.round(player.y/cell),tx=clamp(Math.round(x/cell),3,57),ty=clamp(Math.round(y/cell),4,37);
 if(!walkable(tx*cell,ty*cell)){let best=null;for(let yy=-6;yy<=6;yy++)for(let xx=-6;xx<=6;xx++){let nx=tx+xx,ny=ty+yy;if(walkable(nx*cell,ny*cell)){let dd=Math.hypot(nx*cell-x,ny*cell-y);if(!best||dd<best.d)best={x:nx,y:ny,d:dd};}}if(!best)return;tx=best.x;ty=best.y;}
 const start=sy*cols+sx,end=ty*cols+tx,q=[start],prev=new Map([[start,-1]]);let found=false;
 for(let qi=0;qi<q.length;qi++){let cur=q[qi];if(cur===end){found=true;break;}let cx=cur%cols,cy=Math.floor(cur/cols);for(const [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let nx=cx+dx,ny=cy+dy,n=ny*cols+nx;if(nx<0||nx>=cols||ny<0||ny>=rows||prev.has(n)||!walkable(nx*cell,ny*cell))continue;prev.set(n,cur);q.push(n);}}
 if(found){path=[];for(let cur=end;cur!==start;cur=prev.get(cur))path.unshift({x:(cur%cols)*cell,y:Math.floor(cur/cols)*cell});target={x:tx*cell,y:ty*cell};}
}
// Deterministic full-line timetables. Later trains keep a signal gap behind the
// preceding service; expresses skip real stations without overtaking through objects.
const HEADWAY=58, trainCache=new Map(), built={1:-25,'-1':-25};
function makeTrain(k,dir){
 for(let n=built[dir]+1;n<=k;n++){
  const service=D.services[((n%5)+5)%5],start=n*HEADWAY+(dir===-1?23:0);
  const order=Array.from({length:D.stations.length},(_,i)=>dir===1?i:LAST-i),prev=trainCache.get(`${n-1}:${dir}`);
  let t=start,calls=[];
  for(let i=0;i<order.length;i++){const st=order[i],stop=service.stops.includes(st);let arr=Math.max(t,prev?prev.calls[i].dep+18:t);const dep=arr+(stop?14:0);calls.push({station:st,arr,dep,stop});const edge=dir===1?st:st-1;t=dep+(D.distances[edge]||2)*7.8;}
  // Pass times lie on the same smooth journey between actual stops, so passing
  // trains never decelerate to zero at a skipped station.
  const stopIndices=calls.map((c,i)=>c.stop?i:-1).filter(i=>i>=0);
  for(let n=0;n<stopIndices.length-1;n++){const a=stopIndices[n],b=stopIndices[n+1];for(let j=a+1;j<b;j++){const ratio=(j-a)/(b-a);let lo=0,hi=1;for(let z=0;z<24;z++){const mid=(lo+hi)/2;if(ease(mid)<ratio)lo=mid;else hi=mid;}calls[j].arr=calls[a].dep+(calls[b].arr-calls[a].dep)*(lo+hi)/2;calls[j].dep=calls[j].arr;}}
  trainCache.set(`${n}:${dir}`,{id:`${n}:${dir}`,k:n,dir,service,calls,end:calls.at(-1).dep+10});built[dir]=n;
 }
 return trainCache.get(`${k}:${dir}`);
}
function trainState(tr,t=time){
 const calls=tr.calls,stops=calls.filter(c=>c.stop),first=calls[0],final=tr===onTrain?stops.at(-1):calls.at(-1);
 if(t<first.arr)return{pos:first.station-tr.dir*(first.arr-t)/18,state:'approach',next:stops[0]?.station,door:false};
 if(tr===onTrain&&t>=final.dep)return{pos:final.station,station:final.station,next:final.station,state:'terminal',door:true,remaining:Infinity};
 for(const c of stops){if(t>=c.arr&&t<c.dep)return{pos:c.station,station:c.station,next:c.station,state:t<c.arr+1.7?'braking':t>c.dep-2?'closing':'stopped',door:t>=c.arr+1.7&&t<=c.dep-2,remaining:c.dep-t};}
 const prev=[...stops].reverse().find(c=>c.dep<=t),next=stops.find(c=>c.arr>t);
 // Liner passes the eastern boundary stations without ever opening its doors.
 if((!prev&&next)||(prev&&!next&&t<final.dep)){for(let i=0;i<calls.length-1;i++){const a=calls[i],b=calls[i+1];if(t>=a.dep&&t<b.arr){const f=(t-a.dep)/(b.arr-a.dep);return{pos:a.station+(b.station-a.station)*f,next:next?.station??null,state:'running',door:false};}}}
 if(next){const a=prev||{station:first.station-tr.dir,dep:first.arr-18},f=clamp((t-a.dep)/(next.arr-a.dep),0,1);return{pos:a.station+(next.station-a.station)*ease(f),next:next.station,state:'running',door:false};}
 return{pos:final.station+tr.dir*(t-final.dep)/16,next:null,state:'leaving',door:false};
}
function trains(){const out=[],k=Math.floor(time/HEADWAY);for(let n=k-14;n<=k+5;n++)for(const dir of[1,-1])out.push(makeTrain(n,dir));return out;}
function platformTrains(){return trains().filter(t=>t.dir===direction).map(t=>({tr:t,s:trainState(t),call:t.calls.find(c=>c.station===station)}));}
function boardable(){return platformTrains().find(o=>o.call.stop&&o.s.station===station&&o.s.door);}
function departures(){return platformTrains().filter(o=>o.call.dep>time).sort((a,b)=>a.call.arr-b.call.arr).slice(0,3);}

