function discover(){const st=D.stations[station];if(profile.activeErrand!==st.id){toast('先找广场上的旅行向导接受任务吧。');return;}unlock('souvenirs',st.id);tone(1047,.2);toast(`見つけた！${st.item}。带到${st.landmark}完成任务。`);updateUI();}
